{"cmd": "cd /testbed/security-signoff && python - <<'PY'
import json, yaml
scan=json.load(open("release/RC-17/scan.json"))
scope=yaml.safe_load(open("policy/scan_scope.yaml"))
official=[str(c) for c in scope["components"]]
th=scope.get("thresholds") or {}
fmax=(th.get("default") or {}).get("findings_max",5)
climits=th.get("components") or {}
by={c["component"]:c for c in scan["components"]}
print("scope=%s snapshot=%s findings_max=%s" % (scope.get("scope"), scan.get("snapshot"), fmax))
print("captured components:", sorted(by))
print("missing from capture:", [c for c in official if c not in by])
dirty=[]
for comp in official:
    c=by.get(comp,{})
    lim=climits.get(comp) or {}
    reasons=[]
    n=c.get("findings")
    if isinstance(n,(int,float)) and n>fmax: reasons.append("findings %s > %s"%(n,fmax))
    for k,v in lim.items():
        if k=="exposure_score_max":
            e=c.get("exposure_score")
            if isinstance(e,(int,float)) and e>v: reasons.append("exposure_score %s > %s"%(e,v))
    st=c.get("scan_status")
    if st!="complete": reasons.append("scan_status=%s"%st)
    print("  %-16s status=%-9s findings=%s exposure=%s limits=%s -> %s"
          % (comp,st,n,c.get("exposure_score"),lim or "{}", "CLEAN" if not reasons else "NOT CLEAN: "+", ".join(reasons)))
    if reasons: dirty.append(comp)
print("not-clean official-scope components:", dirty)
print("conclusion:", "clean" if not dirty else "not-clean")
PY"}
